html:
{% if doc.doctype == 'Production Briefing Form' %}
<style>
    .print-format th {
        background-color: black;
        color: white;
        text-align: center;
        font-size: 13px;
        padding: 4px;
    }
    .print-format td {
        font-size: 13px;
        padding: 4px;
        vertical-align: top;
        word-wrap: break-word;
        white-space: normal;
    }
    .section-title {
        font-size: 15px;
        font-weight: bold;
        margin-top: 0px;
        margin-bottom: 0px;
        border-bottom: 1px solid #000;
        padding-bottom: 5px;
    }
    tr, td, th {
        border: none !important;
    }
</style>

<div class="print-format">

    <!-- Header -->
    <div style="width: 100%; overflow: hidden; margin-bottom: 20px; margin-top: -5px;">
        <table style="width: 100%;">
            <tr>
                <td style="width: 40%;">
                    <img src="/files/image_2023_08_24T15_16_35_199Z.png" style="height: 60px;">
                </td>
                <td style="width: 55%; text-align: right;">
                    <h2 style="margin: 0; font-weight: bold;font-size: 27px;">Production Briefing Form</h2>
                </td>
            </tr>
        </table>
    </div>

    <!-- Production Details -->
    <div class="section-title"> </div>
    <table style="width: 100%;">
        <tr>
            <td><strong>ID:</strong> {{ doc.name }}</td>
            <td style="text-align: right;"><strong>Quotation:</strong> {{ doc.quotation }}</td>
        </tr>
        <tr>
            <td><strong>Project:</strong> {{ doc.project }}</td>
            <td style="text-align: right;"><strong>Sales Person:</strong> {{ doc.sales_person }}</td>
        </tr>
        <tr>
            <td><strong>Delivery Date:</strong> {{ frappe.utils.formatdate(doc.expected_delivery_date) }}</td>
            <td style="text-align: right;"><strong>Sales Confirmation Date:</strong> {{ frappe.utils.formatdate(doc.sales_confirmation_date) }}</td>
        </tr>
        <tr>
            <td>
                <strong>Customer:</strong>
                {% if doc.quotation %}
                    {% set quotation = frappe.get_doc("Quotation", doc.quotation) %}
                    {{ quotation.customer_name }}
                {% else %}
                    Unknown
                {% endif %}
            </td>
        </tr>
    </table>

    <!-- Items Table -->
    <div class="section-title"> </div>
    <table style="width: 100%; margin-top: 20px; border-collapse: collapse;">
        <thead>
            <tr>
                <th style="width: 5%; text-align: center;">S.no</th>
                <th style="width: 45%; text-align: left;">Item & Description</th>
                <th style="width: 5%; text-align: left;">Quantity</th>
                <th style="width: 25%; text-align: center;">Image</th>
            </tr>
        </thead>
        <tbody>
        {% for row in doc.briefing_items %}
        <tr style="border-bottom: 1px solid #ccc;">
            <td style="text-align: center;">{{ loop.index }}</td>
            <td>
                <b>{{ row.item_code }}</b><br>
                <b>{{ row.item_name }}</b><br>
                {% if row.description %}{{ row.description }}<br>{% endif %}
                {% if row.custom_design_type %}<b>Design Type:</b>{{row.custom_design_type}}<br>{% endif %}
                {% if row.application %}<b>Application:</b> {{ row.application }}<br>{% endif %}
                {% if row.category %}<b>Door Type:</b> {{ row.category }}<br>{% endif %}
                {% if row.product %}<b>Product Type:</b> {{ row.product }}<br>{% endif %}
                {% if row.frame_type and row.product == 'Frame' %}<b>Frame Type:</b> {{ row.frame_type }}<br>{% endif %}
                {% if row.shutter_type and row.product == 'Shutter' %}<b>Shutter Type:</b> {{ row.shutter_type }}<br>{% endif %}
                {% if row.wood_type %}<b>Wood Type:</b> {{ row.wood_type }}<br>{% endif %}
                {% if row.wood_grade %}<b>Wood Grade:</b> {{ row.wood_grade }}<br>{% endif %}
                {% if row.flush_grade %}<b>Product Grade:</b> {{ row.flush_grade }}<br>{% endif %}
                {% if row.product_size %}<b>Product Size:</b> {{ row.product_size }}<br>{% endif %}
                {% if row.product_thickness %}<b>Thickness:</b> {{ row.product_thickness }}<br>{% endif %}
                {% if row.threshold_thickness %}<b>Threshold Thickness:</b> {{ row.threshold_thickness }}<br>{% endif %}
                {% if row.rebate_thickness %}<b>Rebate Thickness:</b> {{ row.rebate_thickness }}<br>{% endif %}
                {% if row.frame_corner_details %}<b>Frame Corner:</b> {{ row.frame_corner_details }}<br>{% endif %}
                {% if row.load_bearing %}<b>Load Bearing:</b> Yes<br>{% endif %}
                {% if row.frame_design %}<b>Frame Design:</b> {{ row.frame_design }}<br>{% endif %}
                {% if row.custom_theranai_type %}<b>Theranai Type:</b> {{ row.custom_theranai_type }}<br>{% endif %}

                <!-- ✅ FIXED LAMINATE SECTION -->
                {% if row.custom_laminates or row.laminate_thickness %}
                    <b>Laminate:</b> {{ row.custom_laminates }}
                    {% if row.laminate_thickness %}
                        <b> Laminate Thickness:</b> {{ row.laminate_thickness }}
                    {% endif %}
                    <br>
                {% endif %}

                {% if row.anti_termite %}<b>Anti Termite:</b> Included<br>{% endif %}
                {% if row.epoxy %}<b>Epoxy Isolator:</b> Included<br>{% endif %}

                {% if row.grill %}
                    {% if row.grill_details %}
                        <b>Grill Type:</b> {{ row.grill_details }}<br>
                    {% endif %}
                {% endif %}

                {% if row.carving %}
                    {% if row.carving_details %}
                        <b>Carving Type:</b> {{ row.carving_details }}<br>
                    {% endif %}
                {% endif %}

                {% if row.polish %}<b>Polish:</b> Included<br>{% if row.polish_code_with_finish %}<b>Polish Type:</b> {{ row.polish_code_with_finish }}<br>{% endif %}{% endif %}
                {% if row.carving %}<b>Carving:</b> Included<br>{% if row.carving_details %}<b>Carving Type:</b> {{ row.carving_details }}<br>{% endif %}{% endif %}

                {% if row.ornaments %}
                    {% if row.ornaments_details %}
                        <b>Ornaments Type:</b> {{ row.ornaments_details }}<br>
                    {% endif %}
                {% endif %}

                {% if row.veneer_sheet %}<b>Veneer:</b> {{ row.veneer_sheet }}<br>{% endif %}
                {% if row.beading %}<b>Beading:</b> Included<br>{% if row.beading_details %}<b>Beading Type:</b> {{ row.beading_details }}<br>{% endif %}{% endif %}
                {% if row.color_code %}<b>Color Code:</b> {{ row.color_code }}<br>{% endif %}
                {% if row.wpc_colour %}<b>WPC Color:</b> {{ row.wpc_colour }}<br>{% endif %}

                {% if row.hardware %}
                    <b>Hardware Type:</b><br>
                    {% set items = row.hardware_list.split(',') %}
                    {% for i in range(0, items|length, 2) %}
                        {{ items[i].strip() }}{% if i + 1 < items|length %}, {{ items[i + 1].strip() }}{% endif %}<br>
                    {% endfor %}
                {% endif %}

                {% if row.production_measurements %}<b>Measurements:</b> {{ row.production_measurements }}<br>{% endif %}

                {% if row.glass %}
                    {% if row.glass_details %}
                        <b>Glass Type:</b> {{ row.glass_details }}<br>
                    {% endif %}
                {% endif %}

                {% if row.additional_remarks %}<b>Additional Remarks:</b><br>{{ row.additional_remarks | replace('\n', '<br>') | safe }}<br>{% endif %}
                {% if row.polish_location %}<b>Polish Location:</b> {{ row.polish_location }}<br>{% endif %}
                {% if row.custom_open_type %}<b>Open Type:</b> {{ row.custom_open_type }}<br>{% endif %}
            </td>
            <td style="text-align: center; vertical-align: top;">
                {% if row.quantity %}{{ row.quantity }}{% endif %}
            </td>
            <td style="text-align: center; vertical-align: top;">
                {% if row.product_design %}
                <img src="{{ frappe.utils.get_url() }}{{ row.product_design }}" style="max-height: 100%; max-width: -60%;">
                {% endif %}
            </td>
        </tr>
        {% endfor %}
        </tbody>
    </table>

    <!-- Approver -->
    <div class="section-title">Approver Details</div>
    <table style="width: 100%;">
        <tr>
            <td style="font-size: 13px; color: black; text-align: left;">
                <strong>Production Manager:</strong>
                {% if doc.production_incharge %}
                    {% set pm_user = frappe.get_doc("User", doc.production_incharge) %}
                    {{ pm_user.full_name or pm_user.first_name or "Unknown" }}
                {% else %}
                    Unknown
                {% endif %}
            </td>
            <td style="text-align: right;"><strong>Date:</strong> {{ frappe.utils.formatdate(doc.approved_date) }}</td>
        </tr>
    </table>
</div>
{% endif %}
